import { basename, dirname, extname, isInside, join, relativeTo } from "./paths";
import { CuratorSettings, generatedNames } from "./settings";
import { FileKind, VaultFile } from "./types";

export interface CourseInventory {
  name: string;
  folder: string;
  /** Every file of the course except the plugin's own outputs and the archive. */
  files: VaultFile[];
  /** Every sub-folder of the course (vault-relative). */
  folders: string[];
  /** Existing canvases and notes that look like a dashboard / MOC / skill tree. */
  dashboards: string[];
  /** Paths of the files generated by the plugin, when they exist. */
  generated: { canvas: string; index: string; map: string };
  hasMap: boolean;
  structure: StructureSignals;
}

export interface StructureSignals {
  fileCount: number;
  subfolderCount: number;
  maxDepth: number;
  /** Files sitting directly in the course folder. */
  looseFiles: number;
  /** Share of files that live in a sub-folder (0-1): a rough "already organised" indicator. */
  filedRatio: number;
  /** Top-level sub-folders with their file counts. */
  topFolders: { name: string; files: number }[];
}

export interface VaultScan {
  courses: CourseInventory[];
  inbox: VaultFile[];
}

const KINDS: Record<string, FileKind> = {
  md: "markdown",
  pdf: "pdf",
  png: "image",
  jpg: "image",
  jpeg: "image",
  webp: "image",
  gif: "image",
  heic: "image",
  canvas: "canvas",
  docx: "office",
  doc: "office",
  pptx: "office",
  ppt: "office",
  xlsx: "office",
  xls: "office",
  odt: "office",
};

export function fileKind(path: string): FileKind {
  return KINDS[extname(path)] ?? "other";
}

const DASHBOARD_NAME = /dashboard|skill.?tree|\bmoc\b|index|sommaire|overview|carte|roadmap|plan du cours|tableau de bord/i;

export function looksLikeDashboardName(path: string): boolean {
  return fileKind(path) === "canvas" || (fileKind(path) === "markdown" && DASHBOARD_NAME.test(basename(path)));
}

export function fingerprint(file: VaultFile): string {
  return `${file.size}:${Math.round(file.mtime)}`;
}

/**
 * Splits the vault into courses (direct sub-folders of the courses root) and the inbox.
 * Files directly in the courses root are ignored: they belong to no course.
 */
export function scanVault(files: VaultFile[], folders: string[], settings: CuratorSettings): VaultScan {
  const root = settings.coursesRoot;
  const ignored = new Set([...settings.ignoredFolders, settings.inboxFolder].map((f) => f.trim()).filter(Boolean));
  const courseFolders = folders
    .filter((f) => isInside(f, root) && f !== root && dirname(f) === root)
    .filter((f) => !ignored.has(basename(f)) && !basename(f).startsWith("."))
    .sort((a, b) => a.localeCompare(b));

  const inboxPath = join(root, settings.inboxFolder);
  const inbox = files.filter((f) => isInside(f.path, inboxPath));

  const courses = courseFolders.map((folder) => {
    const name = basename(folder);
    const names = generatedNames(settings, name);
    const generated = {
      canvas: join(folder, names.canvas),
      index: join(folder, names.index),
      map: join(folder, names.map),
    };
    const archive = join(folder, settings.archiveFolder);
    const all = files.filter((f) => isInside(f.path, folder));
    const own = new Set(Object.values(generated));
    const courseFiles = all.filter((f) => !own.has(f.path) && !isInside(f.path, archive));
    const subfolders = folders.filter((f) => isInside(f, folder) && f !== folder && !isInside(f, archive));

    return {
      name,
      folder,
      files: courseFiles,
      folders: subfolders,
      dashboards: courseFiles.filter((f) => looksLikeDashboardName(f.path)).map((f) => f.path),
      generated,
      hasMap: all.some((f) => f.path === generated.map),
      structure: structureSignals(folder, courseFiles, subfolders),
    };
  });

  return { courses, inbox };
}

function structureSignals(folder: string, files: VaultFile[], subfolders: string[]): StructureSignals {
  const depth = (p: string) => relativeTo(p, folder).split("/").length - 1;
  const looseFiles = files.filter((f) => depth(f.path) === 0).length;
  const top = subfolders.filter((f) => dirname(f) === folder);
  return {
    fileCount: files.length,
    subfolderCount: subfolders.length,
    maxDepth: files.reduce((m, f) => Math.max(m, depth(f.path)), 0),
    looseFiles,
    filedRatio: files.length ? (files.length - looseFiles) / files.length : 0,
    topFolders: top.map((t) => ({ name: basename(t), files: files.filter((f) => isInside(f.path, t)).length })),
  };
}

/** Indented tree of a course, used in prompts. Paths are relative to the course folder. */
export function renderTree(course: CourseInventory, annotate?: (path: string) => string): string {
  const lines: string[] = [];
  const entries = [
    ...course.folders.map((p) => ({ p, dir: true })),
    ...course.files.map((f) => ({ p: f.path, dir: false })),
  ].sort((a, b) => a.p.localeCompare(b.p));
  for (const { p, dir } of entries) {
    const rel = relativeTo(p, course.folder);
    const indent = "  ".repeat(rel.split("/").length - 1);
    const note = !dir && annotate ? annotate(p) : "";
    lines.push(`${indent}${dir ? "📁 " : ""}${basename(rel)}${dir ? "/" : ""}${note ? `  — ${note}` : ""}`);
  }
  return lines.join("\n");
}
